function hubCrew(val){if(val===undefined||val===null||val==='')return'';var s=String(typeof val==='object'?val.Label||val.Value||val.name||'':val).toUpperCase().trim();if(s.indexOf('256000000')>-1||s==='1')return'A';if(s.indexOf('256000001')>-1||s==='2')return'B';if(s.indexOf('256000002')>-1||s==='3')return'C';if(s.indexOf('256000003')>-1||s==='4')return'D';var m=s.match(/(?:^|[^A-Z])([ABCD])(?=$|[^A-Z])/);return m?m[1]:'';}// FNV-1a with four seeds, shaped like a version 4 GUID (the same swGuid as Ganttly and the Manager hub).
