// ==== PBED HELP ====
// A short how-to for each tab, behind the ? button in the header (data contract 8.6). Every sentence has a Spanish entry.
var PB_HELP={overview:['Executive Overview brings together the entire weekend lifecycle: Thursday Setup, Weekend Execution, and Tuesday Debrief.','Top KPIs track Lines on Plan, Equipment Done (MSS), Key Goalposts, On-Time Start (OTS), Handoff Quality, Work Order PM Completion, Monday Startup Swabs, and Time Lost.','The Live Weekend Timeline compares the planned Gantt chart against actual progress from MSS, Shift Start and Execute.','Month-over-Month PBED Metrics track Major Clean Times, Late Starts by Category, and Monday Startup Swabs by Room across the year.'],plan:['Pick the weekend with Prev, Next or the date box. The page reads the production schedule, equipment, shifts and employees for it.','Each line shows its stop and restart from the clean plan of the Scheduler, or from the production runs until a plan is published. Click a line name to change them, mark an allergen clean or leave the line out.','Milestones are the equipment subcategories in clean order. Click a block to set the people on it, leave out a piece or pick names.','Add Department Callouts (Sanitation, Maintenance, FSQ, Operations) and Weekend Projects with affected areas.','Each line automatically detects whether there are 6+ days of production (only Clear Pallets and Dry Clean required) or standard production (4-step handoff).','Press Save plan. Your Thursday plan is also shared directly into Shift Start (Shift Assistant).'],brief:['The brief is the Friday handoff: key goalposts first, department callouts, projects, then each line with its stop, clean done and restart.','Edit presets changes the OPS and FSQ steps for this weekend only. Make these the default saves them for every weekend.','Add general notes, a note per line and a note per goalpost. They print and copy with the brief.','Copy brief puts the text on the clipboard for Teams or email. Print gives the paper copy.','Save plan keeps the notes and presets with the weekend.'],execute:['See the live Gantt chart comparing where the crew is vs. the plan, and expand any subcategory milestone to check off individual equipment pieces.','Pressing Done + Finish MSS on a sanitation milestone or Finish on an equipment piece writes completion directly to the MSS log (craa5___1_l_log) and Shift Start check-offs.','Verify and submit the Production-to-Sanitation Handoff Checklist, check off Maintenance Work Order PMs, and log the 3 Startup Metrics (Sanitation to FSQ Handoff, Swabs, Product on the Line).','Call out time loss directly from Execute to record delays and mirror them to live floor obstacles.'],debrief:['Tuesday Debrief reviews Clean on Plan, Key Goalposts, On-Time Start (OTS), Handoff Quality, Work Order PMs, Monday Startup Swabs, Labor and Time Lost.','Review and submit each line Handoff Checklist and Startup Metrics. If a line started late, choose the Late Start Category and paste the Teams chat issues.','Log FSQ Inspection status, major findings, failed items, and review or add Monday Startup Swabs (auto-linked from Pathogen BOLO stage = ST).','Review Month-over-Month PBED trends or click Backfill YTD History to enter earlier weekends.'],workorders:['Paste the SAP work order rows (with the header row) or load a .csv file, then Read the paste.','Save the work orders. Ones already saved are updated; their equipment and hours stay.','Pick the area and the equipment for each order once; the page remembers the location for next time.','Tick This weekend to put an order on the weekend plan. Its hours become the maintenance block on the line.'],crew:['Each weekend shift lists who is on it from the Shift Start board, or the Employees roster when there is no board yet.','Double click a name to see their experience by area. An asterisk marks people picked for a milestone on the Plan tab.'],setup:['Developer access: Add me locks Setup and Data to the listed Microsoft accounts. Until someone is listed they stay open to anyone who clicks the logo.','The labor rate is read from the shared _e_ Labor rate table (hub - manager Setup), not typed here.','Each person is costed at the rate of the pay role on their employee row (the Role lookup); no role, or no rate row for it, counts as sanitation tech 2.','Rules, line order and default presets apply to every weekend. Press Save setup when done.','Key goalpost words: a milestone or step with one of these words in its name is starred by itself.'],data:['What this page read: one line per table with Ready, Nothing here yet, Table missing, No access or Could not load. Read again reads everything once more.','Tables this page saves to: Check columns lists any column missing from the _p_ tables. What to build shows in the Dataverse monitor; this page makes nothing.']};function PbHelpModal(props){var tab=props.tab||'plan';var label=(PB_TABS.concat(PB_DEV_TABS).filter(function(t){return t[0]===tab;})[0]||['','Plan'])[1];var steps=PB_HELP[tab]||[];return/*#__PURE__*/React.createElement(PbModal,{title:pbT('Help: {tab}',{tab:pbT(label)}),onClose:props.onClose},/*#__PURE__*/React.createElement("h4",{className:"text-sm font-black text-slate-700"},pbT('How to use this tab')),/*#__PURE__*/React.createElement("ol",{className:"space-y-2 list-decimal pl-5"},steps.map(function(s,i){return/*#__PURE__*/React.createElement("li",{key:i,className:"text-sm text-slate-800"},pbT(s));})));}// ==== END PBED HELP ====
// ==== PBED APP ====
